package com.metabuild.modules.admin.task20;
import static org.assertj.core.api.Assertions.*;import com.metabuild.modules.admin.company.application.*;import com.metabuild.modules.admin.company.persistence.JooqCompanyRepository;import com.metabuild.modules.admin.dictionaries.application.*;import com.metabuild.modules.admin.dictionaries.persistence.JooqDictionaryRepository;import com.metabuild.modules.admin.profile.persistence.JooqProfileRepository;import com.metabuild.shared.kernel.*;import java.util.*;import org.jooq.*;import org.jooq.impl.DSL;import org.junit.jupiter.api.*;
class Task20PostgresRepositoryTest {static DSLContext db;static final UuidV7Generator IDS=new UuidV7Generator();@BeforeAll static void connect(){String url=System.getProperty("task20.pg.url");Assumptions.assumeTrue(url!=null,"set -Dtask20.pg.url for real PostgreSQL");db=DSL.using(url,System.getProperty("task20.pg.user","ocean"),System.getProperty("task20.pg.password",""));}
 @Test void dictionaryCrudPersistsUniqueValuesAndCascadeDelete(){var service=new DictionaryService(new JooqDictionaryRepository(db),IDS);String suffix=IDS.generate().toString().replace("-","").substring(12);var dictionary=service.create("Contract","contract_"+suffix,"test",false);var item=service.createItem(dictionary.id(),"One","one",2,true,"primary","");assertThat(service.items(dictionary.id())).extracting(DictionaryItemView::id).containsExactly(item.id());assertThatThrownBy(()->service.createItem(dictionary.id(),"Duplicate","one",3,true,"neutral","")).isInstanceOf(Conflict.class);service.delete(dictionary.id());assertThat(db.fetchCount(DSL.table("mb_dictionary_item"),DSL.field("dictionary_id").eq(dictionary.id()))).isZero();}
 @Test void companyUpdateIsAuditedInSameDatabase(){var repository=new JooqCompanyRepository(db,IDS);var before=repository.get();UUID actor=UUID.fromString("01900000-0000-7000-8000-000000000010");var value=new CompanyUpdate(before.name(),before.verified(),before.domain(),before.code(),before.industry(),before.scale(),before.dataResidency(),before.createdAt(),before.contactName(),before.contactEmail(),before.contactPhone(),before.landline(),before.address(),before.postalCode());repository.update(actor,value);assertThat(db.fetchCount(DSL.table("mb_operation_log"),DSL.field("operation").eq("company.update").and(DSL.field("actor_id").eq(actor)))).isPositive();}
 @Test void profileReadsBootstrapUserAndPersistsSelfPreferences(){UUID user=UUID.fromString("01900000-0000-7000-8000-000000000010");var repository=new JooqProfileRepository(db);assertThat(repository.get(user).id()).isEqualTo(user);var updated=repository.updatePreferences(user,new com.metabuild.modules.admin.profile.application.PreferenceView("en-US","UTC",false,true));assertThat(updated.language()).isEqualTo("en-US");assertThat(updated.compactNotifications()).isTrue();}
 @Test void passwordChangeIsAtomicAndIncrementsCredentialRevision(){UUID user=UUID.fromString("01900000-0000-7000-8000-000000000010");db.execute("update mb_user set password_hash='hash:old' where id=?",user);var repository=new JooqProfileRepository(db);var codec=new com.metabuild.modules.admin.profile.application.PasswordCodec(){public String hash(String raw){return "hash:"+raw;}public boolean matches(String raw,String encoded){return encoded.equals("hash:"+raw);}};long before=((Number)db.fetchValue("select credential_revision from mb_user where id=?",user,long.class)).longValue();int outbox=db.fetchCount(DSL.table("mb_credential_revocation_outbox"));assertThat(repository.changePasswordWithRecovery(user,"wrong","new-password",null,IDS.generate(),java.time.Duration.ofSeconds(30),codec).changed()).isFalse();assertThat(((Number)db.fetchValue("select credential_revision from mb_user where id=?",user,long.class)).longValue()).isEqualTo(before);var changed=repository.changePasswordWithRecovery(user,"old","new-password",null,IDS.generate(),java.time.Duration.ofSeconds(30),codec);assertThat(changed.changed()).isTrue();assertThat(changed.task().targetCredentialRevision()).isEqualTo(before+1);assertThat(((Number)db.fetchValue("select credential_revision from mb_user where id=?",user,long.class)).longValue()).isEqualTo(before+1);assertThat(db.fetchCount(DSL.table("mb_credential_revocation_outbox"))).isEqualTo(outbox+1);}
 @Test void profileSecondTableFailureRollsBackFirstTableUpdate(){UUID user=UUID.fromString("01900000-0000-7000-8000-000000000010");var repository=new JooqProfileRepository(db);String before=Objects.toString(db.fetchValue("select display_name from mb_user where id=?",user));db.execute("create or replace function task20_profile_fail() returns trigger language plpgsql as $$ begin if new.bio='FORCE_ROLLBACK' then raise exception 'forced second statement failure'; end if; return new; end $$");db.execute("create trigger task20_profile_fail before update on mb_user_profile for each row execute function task20_profile_fail()");try{assertThatThrownBy(()->repository.update(user,new com.metabuild.modules.admin.profile.application.ProfileUpdate("Must Roll Back","","Shanghai","Admin","zh-CN","Asia/Shanghai","FORCE_ROLLBACK"))).isInstanceOf(RuntimeException.class);assertThat(Objects.toString(db.fetchValue("select display_name from mb_user where id=?",user))).isEqualTo(before);}finally{db.execute("drop trigger if exists task20_profile_fail on mb_user_profile");db.execute("drop function if exists task20_profile_fail()");}}
 @Test void databaseRejectsASecondCompany(){assertThatThrownBy(()->db.execute("insert into mb_company(id,name,domain,code,industry,scale,data_residency,created_date,contact_name,contact_email,contact_phone,address,postal_code,singleton_key) values(?,?,?,?,?,?,?,?::date,?,?,?,?,?,1)",IDS.generate(),"Second","second.test","SECOND","Software","1","CN","2026-01-01","Alice","a@second.test","1","Road","1")).isInstanceOf(RuntimeException.class);}
 @Test void credentialWorkerReclaimsExpiredLeaseAndRejectsOldWorkerAba(){db.execute("delete from mb_credential_revocation_outbox");UUID user=UUID.fromString("01900000-0000-7000-8000-000000000010"),event=IDS.generate(),first=IDS.generate(),second=IDS.generate();db.execute("insert into mb_credential_revocation_outbox(id,user_id,credential_revision,protected_session_id) values(?,?,1,'current-session')",event,user);var repository=new JooqProfileRepository(db);var stale=repository.claimCredentialRevocations(first,1,java.time.Duration.ofSeconds(30)).getFirst();db.execute("update mb_credential_revocation_outbox set claimed_at=current_timestamp-interval '2 seconds',lease_until=current_timestamp-interval '1 second' where id=?",event);var current=repository.claimCredentialRevocations(second,1,java.time.Duration.ofSeconds(30)).getFirst();assertThat(current.attempt()).isEqualTo(stale.attempt()+1);assertThat(repository.completeCredentialRevocation(stale)).isFalse();assertThat(repository.failCredentialRevocation(stale,"late")).isFalse();assertThat(repository.completeCredentialRevocation(current)).isTrue();assertThat(db.fetchValue("select status from mb_credential_revocation_outbox where id=?",event,String.class)).isEqualTo("DONE");}
}
